#pragma once
#include "rinkfit/joint_packet.hpp"
#include <ceres/ceres.h>
#include <Eigen/Dense>
#include <mutex>
namespace rinkfit {
struct JointRowEvaluation {
 const JointEventModel*model=nullptr;JointRowLayout layout;const JointObservation*observation=nullptr;int station_slot=-1,geometry_size=0;bool observed_row_time_initialization=false,require_physical_visibility=false;struct RootCache{std::mutex mutex;std::vector<double>key;std::array<double,3>x{};Eigen::Matrix3d J;bool valid=false,has=false;};std::shared_ptr<RootCache>cache=std::make_shared<RootCache>();std::map<int,int>parameter_sizes;
 JointRowEvaluation remap(const std::vector<int>& map)const{auto q=*this;auto re=[&](int i){return i<0?i:map.at(i);};q.layout.scene_slot=re(layout.scene_slot);q.layout.rig_slot=re(layout.rig_slot);q.layout.optics_slot=re(layout.optics_slot);q.layout.reference_angles_slot=re(layout.reference_angles_slot);q.layout.geometry_slot=re(layout.geometry_slot);q.layout.advertisement_slot=re(layout.advertisement_slot);q.layout.width_slot=re(layout.width_slot);for(auto& i:q.layout.control_slots)i=re(i);q.station_slot=re(station_slot);q.parameter_sizes.clear();for(auto z:parameter_sizes)q.parameter_sizes[re(z.first)]=z.second;return q;}
 template<class T>bool local_solution_uncached(T const*const*pars,double station,std::array<double,3>*x,Eigen::Matrix3d*J)const{
  std::vector<std::vector<double>> store;std::vector<const double*>p;int maxslot=-1;for(auto z:parameter_sizes)maxslot=std::max(maxslot,z.first);store.resize(maxslot+1);p.resize(maxslot+1);for(auto z:parameter_sizes){store[z.first].resize(z.second);for(int k=0;k<z.second;++k)store[z.first][k]=event_scalar(pars[z.first][k]);p[z.first]=store[z.first].data();}
  if(!observation->station_allowed(*model,layout.path,station) ||
     !std::isfinite(observation->row) || observation->row<0 || observation->row>1079)return false;
  if(observation->kind==1 && observation->query)return false; // A fixed entity never slides along a Query.
  *x={station,observation->row,observation->alpha};
  if(!observation->query){for(int it=0;it<16;++it){using K=ceres::Jet<double,1>;std::vector<std::vector<K>>ks;std::vector<const K*>kp;for(auto&v:store){ks.emplace_back();for(auto a:v)ks.back().push_back(K(a));kp.push_back(ks.back().data());}K row((*x)[1]);row.v[0]=1;Projection<K>out;try{out=model->predict_explicit(layout,K(station),row,kp.data());}catch(...){return false;}if(!out.valid())return false;double F=(*x)[1]-out.uv[1].a,den=1-out.uv[1].v[0];if(!std::isfinite(den)||std::abs(den)<1e-6)return false;(*J).setZero();(*J)(0,0)=den;if(std::abs(F)<1e-8)return true;double next=(*x)[1]-F/den;if(next<0||next>1079)return false;(*x)[1]=next;}return false;}
  for(int it=0;it<20;++it){using K=ceres::Jet<double,3>;std::vector<std::vector<K>>ks;std::vector<const K*>kp;for(auto&v:store){ks.emplace_back();for(auto a:v)ks.back().push_back(K(a));kp.push_back(ks.back().data());}K s((*x)[0]),row((*x)[1]),alpha((*x)[2]);s.v[0]=1;row.v[1]=1;alpha.v[2]=1;Projection<K>out;Vec2<K>q;try{out=model->predict_explicit(layout,s,row,kp.data());}catch(...){return false;}if(!out.valid()||!observation->query->point(alpha,&q))return false;std::array<K,3>F={row-out.uv[1],out.uv[0]-q[0],out.uv[1]-q[1]};Eigen::Vector3d f;for(int i=0;i<3;++i){f[i]=F[i].a;for(int j=0;j<3;++j)(*J)(i,j)=F[i].v[j];}if(f.lpNorm<Eigen::Infinity>()<1e-8)return observation->station_allowed(*model,layout.path,(*x)[0]) && (*x)[1]>=0 && (*x)[1]<=1079 && J->fullPivLu().rank()==3;Eigen::FullPivLU<Eigen::Matrix3d>lu(*J);if(lu.rank()!=3)return false;auto d=lu.solve(-f);double step=1;bool ok=false;for(int k=0;k<12;++k){auto y=*x;for(int a=0;a<3;++a)y[a]+=step*d[a];if(observation->station_allowed(*model,layout.path,y[0])&&y[1]>=0&&y[1]<=1079&&y[2]>=observation->query->alpha.front()&&y[2]<=observation->query->alpha.back()){auto o=model->predict_explicit(layout,y[0],y[1],p.data());Vec2<double>z;if(o.valid()&&observation->query->point(y[2],&z)){Eigen::Vector3d fn;fn<<y[1]-o.uv[1],o.uv[0]-z[0],o.uv[1]-z[1];if(fn.squaredNorm()<f.squaredNorm()){*x=y;ok=true;break;}}}step*=.5;}if(!ok)return false;}return false;
 }
 template<class T>bool local_solution(T const*const*pars,double station,std::array<double,3>*x,Eigen::Matrix3d*J)const{std::vector<double>key={station};const auto&sizes=parameter_sizes;for(auto z:sizes)for(int j=0;j<z.second;++j)key.push_back(event_scalar(pars[z.first][j]));std::lock_guard<std::mutex>lock(cache->mutex);if(cache->has&&cache->key==key){*x=cache->x;*J=cache->J;return cache->valid;}*x={0,0,0};J->setZero();bool ok=local_solution_uncached(pars,station,x,J);cache->key=std::move(key);cache->x=*x;cache->J=*J;cache->valid=ok;cache->has=true;return ok;}
 template<class T>bool nuisance(T const*const*pars,std::array<T,3>*y)const{
  double station=station_slot<0?observation->station:event_scalar(pars[station_slot][0]);std::array<double,3>x{};Eigen::Matrix3d J=Eigen::Matrix3d::Zero();if(!local_solution(pars,station,&x,&J))return false;
  if(!observation->query){const T s=station_slot<0?T(x[0]):pars[station_slot][0];auto p=model->predict_explicit(layout,s,T(x[1]),pars);const T row=T(x[1])-(T(x[1])-p.uv[1])/T(J(0,0));*y={s,row,T(x[2])};return true;}
  auto p=model->predict_explicit(layout,T(x[0]),T(x[1]),pars);Vec2<T>q;if(!observation->query->point(T(x[2]),&q))return false;std::array<T,3>F={T(x[1])-p.uv[1],p.uv[0]-q[0],p.uv[1]-q[1]};*y={T(x[0]),T(x[1]),T(x[2])};Eigen::Matrix3d inv=J.inverse();for(int i=0;i<3;++i)for(int j=0;j<3;++j)(*y)[i]-=T(inv(i,j))*F[j];return true;
 }
 template<class T>bool predict(T const*const*pars,Projection<T>*out)const{if(observed_row_time_initialization){if(observation->query)return false;const T s=station_slot<0?T(observation->station):pars[station_slot][0];if(!observation->station_allowed(*model,layout.path,event_scalar(s)))return false;*out=model->predict_explicit(layout,s,T(observation->uv[1]),pars);return out->valid()&&(!require_physical_visibility||model->visibility(layout,s,T(observation->uv[1]),pars).visible());}std::array<T,3>y;if(!nuisance(pars,&y))return false;*out=model->predict_explicit(layout,y[0],y[1],pars);return out->valid()&&(!require_physical_visibility||model->visibility(layout,y[0],y[1],pars).visible());}
 template<class T>bool native_error(T const*const*p,Vec2<T>*error)const{Projection<T>uv;try{if(!predict(p,&uv))return false;*error={uv.uv[0]-T(observation->uv[0]),uv.uv[1]-T(observation->uv[1])};return finite_array(*error);}catch(...){return false;}}
};
struct JointGroupedStatistic {const JointStatisticalGroup*group=nullptr;std::vector<JointRowEvaluation>rows;template<class T>bool operator()(T const*const*p,T*r)const{std::vector<T>e(2*rows.size());for(std::size_t i=0;i<rows.size();++i){Vec2<T>x;if(!rows[i].native_error(p,&x))return false;e[2*i]=x[0];e[2*i+1]=x[1];}for(std::size_t i=0;i<group->rank;++i){T sum=T(0);for(std::size_t j=0;j<e.size();++j)if(group->W[i*e.size()+j]!=0)sum+=T(group->W[i*e.size()+j])*e[j];r[i]=sum;if(!finite_scalar(sum))return false;}return true;}};
}
